'use strict';
const nEscape=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function nRequest(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options});const data=await response.json().catch(()=>({error:'Could not reach GLOSS. Please try again.'}));if(!response.ok)throw Error(data.error||'Could not complete this request.');return data;}
const nPost=(path,body)=>nRequest(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});
if(document.querySelector('#agency-directory-grid')){let agencies=[];const grid=document.querySelector('#agency-directory-grid'),empty=document.querySelector('#agency-directory-empty'),status=document.querySelector('#agency-results-status');function renderDirectory(){const search=document.querySelector('#agency-search').value.trim().toLowerCase(),relationship=document.querySelector('#agency-relationship').value,freshers=document.querySelector('#agency-freshers').value;const visible=agencies.filter(a=>(relationship==='all'||a.relationship===relationship)&&(freshers==='all'||a.freshers==='yes')&&`${a.name} ${a.city} ${a.specialties}`.toLowerCase().includes(search));status.textContent=agencies.length?`${visible.length} of ${agencies.length} agencies shown`:'No agencies published yet';empty.hidden=visible.length>0;empty.querySelector('h3').innerHTML=agencies.length?'No listings match<br>this search.':'The network starts<br>with real conversations.';empty.querySelector('p').textContent=agencies.length?'Try another city, specialty or experience filter.':'There are no published agencies yet. GLOSS is inviting collaborators; agreed listings will appear here. No agency names or partnerships are being invented.';grid.innerHTML=visible.map(a=>`<article class="agency-card"><div class="agency-card-top"><span>${a.relationship==='confirmed'?'GLOSS PARTNER':'AGENCY CONTACT'}</span><span>${nEscape(a.city)}</span></div><div class="agency-monogram">${nEscape(a.name.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</div><h3>${nEscape(a.name)}</h3><p>${nEscape(a.description)}</p><div class="agency-tags">${a.specialties.split(',').map(t=>t.trim()).filter(Boolean).map(t=>`<span>${nEscape(t)}</span>`).join('')}</div><div class="fresher-status">${a.freshers==='yes'?'● Confirmed open to freshers':a.freshers==='no'?'Experienced talent focus':'Fresher acceptance not confirmed'}</div><a class="network-button" href="${nEscape(a.application_url||a.website)}" target="_blank" rel="noopener noreferrer">Official ${a.application_url?'submission page':'website'} ↗</a><small>${a.relationship==='confirmed'?'Collaboration confirmed by GLOSS. Follow the agency’s own application process.':'Listed as an agency contact. No GLOSS partnership is implied.'}</small></article>`).join('');}document.querySelector('#agency-filters').onsubmit=e=>e.preventDefault();document.querySelectorAll('#agency-filters input,#agency-filters select').forEach(el=>el.addEventListener('input',renderDirectory));nRequest('/api/network/agencies').then(data=>{agencies=data.agencies;renderDirectory();}).catch(error=>{status.textContent=error.message;});}
const interest=document.querySelector('#partner-interest-form');if(interest)interest.onsubmit=async e=>{e.preventDefault();if(!interest.reportValidity())return;const button=interest.querySelector('button'),status=document.querySelector('#partner-interest-status'),data=Object.fromEntries(new FormData(interest));data.consent=interest.elements.consent.checked;button.disabled=true;status.textContent='Saving your request…';try{const result=await nPost('/api/network/interest',data);status.textContent=result.message;interest.reset();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
if(document.body.dataset.networkView==='admin'){const form=document.querySelector('#agency-editor'),list=document.querySelector('#agency-admin-list'),status=document.querySelector('#agency-editor-status');let listings=[];function resetEditor(){form.reset();form.elements.id.value='';document.querySelector('#agency-editor-heading').textContent='Add an agency';}
async function loadAgencies(){const data=await nRequest('/api/network/admin/agencies');listings=data.agencies;list.innerHTML=listings.length?listings.map(a=>`<article class="agency-desk-row"><div><b>${nEscape(a.name)}</b><p>${nEscape(a.city)} · ${a.published?'Published':'Draft'} · ${a.relationship==='confirmed'?'Confirmed partner':'Agency contact'}</p><small>Referral visits: ${a.referral_visits} · Verified sales and payouts: not connected</small>${a.referral_enabled?`<label>Referral link<input value="${nEscape(a.referral_url)}" readonly></label>`:''}</div><div><button class="network-outline" type="button" data-edit-agency="${nEscape(a.id)}">Edit listing</button>${a.referral_enabled?`<button class="network-outline" type="button" data-copy-referral="${nEscape(a.id)}">Copy referral link</button>`:''}</div></article>`).join(''):'<p>No agencies yet. Add an agreed listing below.</p>';list.querySelectorAll('[data-edit-agency]').forEach(button=>button.onclick=()=>{const a=listings.find(x=>x.id===button.dataset.editAgency);for(const[key,value]of Object.entries(a)){if(key==='modeling_fields'){form.querySelectorAll('[name=modeling_fields]').forEach(input=>input.checked=(value||'').split(',').includes(input.value));continue;}const el=form.elements.namedItem(key);if(!el)continue;if(el.type==='checkbox')el.checked=!!value;else el.value=value;}form.elements.permission.checked=false;document.querySelector('#agency-editor-heading').textContent='Edit '+a.name;form.scrollIntoView({behavior:'smooth'});});list.querySelectorAll('[data-copy-referral]').forEach(button=>button.onclick=async()=>{const a=listings.find(x=>x.id===button.dataset.copyReferral);try{await navigator.clipboard.writeText(a.referral_url);status.textContent='Referral link copied. It tracks visits, not purchases or payable commission.';}catch{status.textContent='Copy the referral URL shown in the listing above.';}});}
async function loadRequests(){const data=await nRequest('/api/network/admin/requests'),target=document.querySelector('#agency-request-list');target.innerHTML=data.requests.length?data.requests.map(r=>`<article class="request-card"><div class="request-heading"><h3>${nEscape(r.agency_name)}</h3><span>${nEscape(r.status)}</span></div><p>${nEscape(r.contact_name)} · ${nEscape(r.city)}</p><p>${nEscape(r.email)}</p><a href="${nEscape(r.website)}" target="_blank" rel="noopener noreferrer">Official website ↗</a><p class="request-message">${nEscape(r.message)}</p><small>Received ${new Date(r.created_at).toLocaleString()}</small>${r.status==='new'?`<button class="network-outline" type="button" data-review-request="${nEscape(r.id)}">Mark reviewed</button>`:''}</article>`).join(''):'<p>No partnership requests yet.</p>';target.querySelectorAll('[data-review-request]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await nPost('/api/network/admin/requests/reviewed',{id:button.dataset.reviewRequest});await loadRequests();}catch(error){status.textContent=error.message;button.disabled=false;}});}
document.querySelector('#agency-new').onclick=resetEditor;form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;const body=Object.fromEntries(new FormData(form));for(const k of ['permission','published','referral_enabled'])body[k]=form.elements[k].checked;body.modeling_fields=[...form.querySelectorAll('[name=modeling_fields]:checked')].map(input=>input.value);const button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent='Saving agency listing…';try{await nPost('/api/network/admin/agencies',body);await loadAgencies();resetEditor();status.textContent='Agency saved. Its public visibility follows the Publish checkbox.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};document.querySelectorAll('[data-desk-tab]').forEach(button=>button.onclick=()=>{const requests=button.dataset.deskTab==='requests';document.querySelector('#desk-listings').hidden=requests;document.querySelector('#desk-requests').hidden=!requests;document.querySelectorAll('[data-desk-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));if(requests)loadRequests().catch(error=>{document.querySelector('#agency-request-list').textContent=error.message;});});loadAgencies().catch(error=>{status.textContent=error.message;});}
